#include <iostream>
#include <string>

int main() {
    std::string query;
    if (!std::getline(std::cin, query)) return 1;
    std::size_t amp = query.find('&');
    if (amp == std::string::npos) return 1;
    std::string first = query.substr(0, amp);
    std::string second = query.substr(amp + 1);
    if (second.find('&') != std::string::npos) return 1;
    std::size_t eq1 = first.find('=');
    std::size_t eq2 = second.find('=');
    if (eq1 == std::string::npos || eq2 == std::string::npos) return 1;
    std::string key1 = first.substr(0, eq1);
    std::string value1 = first.substr(eq1 + 1);
    std::string key2 = second.substr(0, eq2);
    std::string value2 = second.substr(eq2 + 1);
    if (key1 != "name" || key2 != "age") return 1;
    if (value1.empty() || value2.empty()) return 1;
    if (value1.find(' ') != std::string::npos || value2.find(' ') != std::string::npos) return 1;
    std::cout << "Content-Type: text/plain\n\n";
    std::cout << "name=" << value1 << "\n";
    std::cout << "age=" << value2 << "\n";
    return 0;
}

