#include <iostream>
#include <string>
#include <vector>

template <typename T>
T total_of(const std::vector<T>& items) {
    T total = T();
    for (const T& item : items) {
        total += item;
    }
    return total;
}

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 1;
    int n = 0;
    try {
        std::size_t pos = 0;
        n = std::stoi(line, &pos);
        if (pos != line.size()) return 1;
    } catch (...) {
        return 1;
    }
    if (n < 1 || n > 1000) return 1;
    std::vector<int> nums;
    std::vector<std::string> words;
    for (int i = 0; i < n; i++) {
        if (!std::getline(std::cin, line)) return 1;
        std::size_t space = line.find(' ');
        if (space == std::string::npos) return 1;
        std::string kind = line.substr(0, space);
        std::string rest = line.substr(space + 1);
        if (rest.empty() || rest.find(' ') != std::string::npos) return 1;
        if (kind == "num") {
            int value = 0;
            try {
                std::size_t pos = 0;
                value = std::stoi(rest, &pos);
                if (pos != rest.size()) return 1;
            } catch (...) {
                return 1;
            }
            if (value < 0 || value > 100) return 1;
            nums.push_back(value);
        } else if (kind == "word") {
            for (char ch : rest) {
                if (ch < 'a' || ch > 'z') return 1;
            }
            words.push_back(rest);
        } else {
            return 1;
        }
    }
    std::cout << "nums " << total_of(nums) << "\n";
    std::cout << "words " << total_of(words) << "\n";
    return 0;
}
